(6773250, 1016037, 62249, '<td valign="top">Odd title but fascinating shot. I love the high contrast and the limited color palette. The highlight on the left edge of the bowl is a very nice touch. Debating with myself about whether I''d like it better without the hand shadow. I think it''s a draw.</td>', 'Odd title but fascinating shot. I love the high contrast and the limited color palette. The highlight on the left edge of the bowl is a very nice touch. Debating with myself about whether I''d like it better without the hand shadow. I think it''s a draw.', '2012-05-19 17:59:28.000000', NULL, 1),
(6773251, 1015977, 62249, '<td valign="top">Not fond of the border, but the image itself is very good. Love the highlights on the young birds'' bills, and the mom in the background really helps tell the story.</td>', 'Not fond of the border, but the image itself is very good. Love the highlights on the young birds'' bills, and the mom in the background really helps tell the story.', '2012-05-19 18:06:43.000000', NULL, 1),
(6773253, 1015871, 62249, '<td valign="top">I love this! The backlighting highlighting the edges of the vegetation and the slug''s "horns" is gorgeous. Love the texture on the slug, too.</td>', 'I love this! The backlighting highlighting the edges of the vegetation and the slug''s "horns" is gorgeous. Love the texture on the slug, too.', '2012-05-19 18:09:19.000000', NULL, 1),
