(6774153, 1015958, 114285, '<td valign="top">Awesome shot, hope you do well, b/c it looks like real rain to me.</td>', 'Awesome shot, hope you do well, b/c it looks like real rain to me.', '2012-05-21 04:56:37.000000', NULL, 1),
