(6774389, 1016066, 10848, '<td valign="top">Creative and interesting image.</td>', 'Creative and interesting image.', '2012-05-21 12:08:22.000000', NULL, 1),
(6774390, 1015979, 10848, '<td valign="top">Love it!</td>', 'Love it!', '2012-05-21 12:08:33.000000', NULL, 1),
