(6774424, 1015043, 96664, '<td valign="top">That looks like snow but either way a stunning image! Well done!</td>', 'That looks like snow but either way a stunning image! Well done!', '2012-05-21 13:14:34.000000', NULL, 1),
(6774426, 1015663, 96664, '<td valign="top">A touch blurry. Wish it would have been sharp. Could have had potential for a ribbon if that were the case.</td>', 'A touch blurry. Wish it would have been sharp. Could have had potential for a ribbon if that were the case.', '2012-05-21 13:15:48.000000', NULL, 1),
(6774430, 1016053, 96664, '<td valign="top">This looks like Christophe''s work. <br/> <br/>Couple things I like about this.. One, the tree looks pretty awesome. Two, the rainbow perfectly centered over the pipe. One thing I don''t like about this though is the person. In my opinion it doesn''t add anything more. In fact to me it clutters it a little. Giving it an 8. Well done overall though.</td>', 'This looks like Christophe''s work.  Couple things I like about this.. One, the tree looks pretty awesome. Two, the rainbow perfectly centered over the pipe. One thing I don''t like about this though is the person. In my opinion it doesn''t add anything more. In fact to me it clutters it a little. Giving it an 8. Well done overall though.', '2012-05-21 13:18:17.000000', NULL, 1),
(6774431, 1016041, 96664, '<td valign="top">I love this one!!! Very emotional! Well done!</td>', 'I love this one!!! Very emotional! Well done!', '2012-05-21 13:18:58.000000', NULL, 1),
(6774433, 1014976, 96664, '<td valign="top">Wish the boy was facing the camera to see the determination on his face! I love the post process on this though! Well done!</td>', 'Wish the boy was facing the camera to see the determination on his face! I love the post process on this though! Well done!', '2012-05-21 13:20:13.000000', NULL, 1),
(6774434, 1015543, 96664, '<td valign="top">Well done man! Your 30 day self portrait SC is really paying off! Getting better and better with every shot! Well done.</td>', 'Well done man! Your 30 day self portrait SC is really paying off! Getting better and better with every shot! Well done.', '2012-05-21 13:21:10.000000', NULL, 1),
