(6774876, 1015894, 54446, '<td valign="top">Fantastic!  10</td>', 'Fantastic!  10', '2012-05-21 21:40:19.000000', NULL, 1),
(6774878, 1016053, 54446, '<td valign="top">It''s a beautiful image, but it''s not photographic in nature.  By that, I mean one would never see this with one''s eyes.  It''s a joy to view, but it''s pure fantasy.  Since this is an expert edit challenge, I will mark this 10, but I don''t accept it as a photograph.  Really enjoy your ability to draw and paint.  No offense intended.</td>', 'It''s a beautiful image, but it''s not photographic in nature.  By that, I mean one would never see this with one''s eyes.  It''s a joy to view, but it''s pure fantasy.  Since this is an expert edit challenge, I will mark this 10, but I don''t accept it as a photograph.  Really enjoy your ability to draw and paint.  No offense intended.', '2012-05-21 21:40:44.000000', NULL, 1),
(6774881, 1016047, 54446, '<td valign="top">Love it!  10</td>', 'Love it!  10', '2012-05-21 21:41:57.000000', NULL, 1),
(6774882, 1016041, 54446, '<td valign="top">I don''t know what those red things are.  But, the rest of the image has great <i>gravitas</i>.  10</td>', 'I don''t know what those red things are.  But, the rest of the image has great gravitas.  10', '2012-05-21 21:42:49.000000', NULL, 1),
(6774936, 1015865, 69246, '<td valign="top">Freaks me out...but a great photo.</td>', 'Freaks me out...but a great photo.', '2012-05-21 23:12:50.000000', NULL, 1),
(6775029, 1014976, 54446, '<td valign="top">One of my few 10s in this challenge.  This really meets the challenge well.  I love the sel desat.  This is an award winning photograph!  10</td>', 'One of my few 10s in this challenge.  This really meets the challenge well.  I love the sel desat.  This is an award winning photograph!  10', '2012-05-22 03:53:38.000000', NULL, 1),
(6775088, 1016033, 147852, '<td valign="top">I really like your idea but the pole in the foreground spoils it for me.</td>', 'I really like your idea but the pole in the foreground spoils it for me.', '2012-05-22 07:24:35.000000', NULL, 1),
(6775094, 1015862, 22459, '<td valign="top">Where is the focal point.......sorry too much too look at.</td>', 'Where is the focal point.......sorry too much too look at.', '2012-05-22 07:47:16.000000', NULL, 1),
(6775202, 1015905, 132996, '<td valign="top">A very intense gaze and really nice texture on the fringe of the cloak. I''m not completely sure whether I like the strand of hair in her face...I can see people loving or hating it. It does keep the viewer in the image, as a plus.</td>', 'A very intense gaze and really nice texture on the fringe of the cloak. I''m not completely sure whether I like the strand of hair in her face...I can see people loving or hating it. It does keep the viewer in the image, as a plus.', '2012-05-22 10:31:48.000000', NULL, 1),
(6775210, 1015270, 132996, '<td valign="top">There''s a lot flying by in the image! I like the textures on the ground and the seeming movement of his front feet. The composition is a bit bland, a more solid decision of his position in the frame needs to be made in my opinion.</td>', 'There''s a lot flying by in the image! I like the textures on the ground and the seeming movement of his front feet. The composition is a bit bland, a more solid decision of his position in the frame needs to be made in my opinion.', '2012-05-22 10:34:25.000000', NULL, 1),
(6775222, 1015663, 132996, '<td valign="top">Love this. The detail is incredibly subtle and the gentle curves make my eyes twist and turn back and forth in a melody.</td>', 'Love this. The detail is incredibly subtle and the gentle curves make my eyes twist and turn back and forth in a melody.', '2012-05-22 10:42:48.000000', NULL, 1),
(6775223, 1015930, 132996, '<td valign="top">I like the attempt to divide the image into foreground and background diagonally, however I think this image lacks a solid focal point. If you could have made that rainbow pop a little more intensely, I think it would be a winning shot.</td>', 'I like the attempt to divide the image into foreground and background diagonally, however I think this image lacks a solid focal point. If you could have made that rainbow pop a little more intensely, I think it would be a winning shot.', '2012-05-22 10:44:21.000000', NULL, 1),
(6775224, 1016033, 43565, '<td valign="top">I like the idea, however I find the pole in the foreground distracting.</td>', 'I like the idea, however I find the pole in the foreground distracting.', '2012-05-22 10:46:50.000000', NULL, 1),
(6775231, 1016018, 114225, '<td valign="top">Cool take on the challenge, and good use of the rule set.</td>', 'Cool take on the challenge, and good use of the rule set.', '2012-05-22 10:51:44.000000', NULL, 1),
(6775232, 1015958, 114225, '<td valign="top">In my opinion, this could have been much nicer without that big vignette covering so much of the interest in this scene.</td>', 'In my opinion, this could have been much nicer without that big vignette covering so much of the interest in this scene.', '2012-05-22 10:52:38.000000', NULL, 1),
(6775233, 1016047, 114225, '<td valign="top">Very cute example. I like how the pink shirt sticks out against the background so well.</td>', 'Very cute example. I like how the pink shirt sticks out against the background so well.', '2012-05-22 10:53:07.000000', NULL, 1),
(6775235, 1015988, 114225, '<td valign="top">Very cool interpretation. What really makes this come alive is the shine to the dress.</td>', 'Very cool interpretation. What really makes this come alive is the shine to the dress.', '2012-05-22 10:54:09.000000', NULL, 1),
(6775236, 1016033, 114225, '<td valign="top">Ha! Great use of imagination.</td>', 'Ha! Great use of imagination.', '2012-05-22 10:54:57.000000', NULL, 1),
