(6778054, 1015988, 19825, '<td valign="top">Beautiful shot and seamless processing. Congrats on the top 10 finish.</td>', 'Beautiful shot and seamless processing. Congrats on the top 10 finish.', '2012-05-25 06:49:24.000000', NULL, 0),
